-- Bulk-imports 211 real Dubai developers (from a directory export) that
-- aren't already on the platform, as unclaimed/unverified records --
-- status 'pending', no linked auth account. Matches the existing
-- self-service onboarding model (DeveloperOnboarding.tsx, patch_37): if
-- one of these companies later signs up for real, they claim their row by
-- linking profile.developer_id to it rather than getting a duplicate.
--
-- 6 entries from the source list were excluded because they're the same
-- company (under a slightly different name) as a developer already on the
-- platform with real projects attached: Binghatti Developers -> Binghatti,
-- Damac Properties -> DAMAC Properties, Ellington Properties (exact),
-- Emaar Properties (exact), Nakheel (exact), Sobha Realty (exact).
--
-- Idempotent: skips any name that already exists (case-insensitive), so
-- this is safe to re-run.
insert into developers (slug, name, initial, founded, website, logo_url, status, verified)
select v.slug, v.name, v.initial, v.founded, v.website, v.logo_url, v.status, v.verified
from (values
